module hipfort_hipblas
  use hipfort_hipblas_enums
  use hipfort_hipblas_types
  use hipfort_handles
  use, intrinsic :: iso_c_binding
  implicit none

  interface

    !---------------------------------------------
    ! hipblasSetVector
    !---------------------------------------------
    !> \brief Copy vector from host to device.
    !> @param[in]
    !> n           [int]
    !> number of elements in the vector.
    !> @param[in]
    !> elemSize    [int]
    !> Size of both vectors in bytes.
    !> @param[in]
    !> x           pointer to vector on the host.
    !> @param[in]
    !> incx        [int]
    !> specifies the increment for the elements of the vector.
    !> @param[out]
    !> y           pointer to vector on the device.
    !> @param[in]
    !> incy        [int]
    !> specifies the increment for the elements of the vector.
    function hipblasSetVector(n, elemSize, x, incx, y, incy) &
       result(SetVector) &
#ifdef USE_CUDA_NAMES
       bind(C, name="cublasSetVector")
#else
       bind(C, name="hipblasSetVector")
#endif
       import :: c_int, c_ptr
       integer(c_int), value :: n
       integer(c_int), value :: elemSize
       type(c_ptr), value :: x
       integer(c_int), value :: incx
       type(c_ptr), value :: y
       integer(c_int), value :: incy
       integer(c_int) :: SetVector
    end function hipblasSetVector

    !---------------------------------------------
    ! hipblasGetVector
    !---------------------------------------------
    !> \brief Copy vector from device to host.
    !> @param[in]
    !> n           [int]
    !> number of elements in the vector.
    !> @param[in]
    !> elemSize    [int]
    !> Size of both vectors in bytes.
    !> @param[in]
    !> x           pointer to vector on the device.
    !> @param[in]
    !> incx        [int]
    !> specifies the increment for the elements of the vector.
    !> @param[out]
    !> y           pointer to vector on the host.
    !> @param[in]
    !> incy        [int]
    !> specifies the increment for the elements of the vector.
    function hipblasGetVector(n, elemSize, x, incx, y, incy) &
       result(GetVector) &
#ifdef USE_CUDA_NAMES
       bind(C, name="cublasGetVector")
#else
       bind(C, name="hipblasGetVector")
#endif
       import :: c_int, c_ptr
       integer(c_int), value :: n
       integer(c_int), value :: elemSize
       type(c_ptr), value :: x
       integer(c_int), value :: incx
       type(c_ptr), value :: y
       integer(c_int), value :: incy
       integer(c_int) :: GetVector
    end function hipblasGetVector

    !---------------------------------------------
    ! hipblasSetMatrix
    !---------------------------------------------
    !> \brief Copy matrix from host to device.
    !> @param[in]
    !> rows        [int]
    !> number of rows in the matrix.
    !> @param[in]
    !> cols        [int]
    !> number of columns in the matrix.
    !> @param[in]
    !> elemSize   [int]
    !> number of bytes per element in the matrix.
    !> @param[in]
    !> AP          pointer to matrix on the host.
    !> @param[in]
    !> lda         [int]
    !> specifies the leading dimension of A. lda >= rows.
    !> @param[out]
    !> BP           pointer to matrix on the GPU.
    !> @param[in]
    !> ldb         [int]
    !> specifies the leading dimension of B. ldb >= rows.
    function hipblasSetMatrix(rows, cols, elemSize, AP, lda, BP, ldb) &
       result(SetMatrix) &
#ifdef USE_CUDA_NAMES
       bind(C, name="cublasSetMatrix")
#else
       bind(C, name="hipblasSetMatrix")
#endif
       import :: c_int, c_ptr
       integer(c_int), value :: rows
       integer(c_int), value :: cols
       integer(c_int), value :: elemSize
       type(c_ptr), value :: AP
       integer(c_int), value :: lda
       type(c_ptr), value :: BP
       integer(c_int), value :: ldb
       integer(c_int) :: SetMatrix
    end function hipblasSetMatrix

