       type(c_ptr), value :: handle
       integer(c_int), value :: uplo
       integer(c_int), value :: n
       real(c_float) :: alpha
       type(c_ptr), value :: x
       integer(c_int), value :: incx
       integer(c_long), value :: stridex
       type(c_ptr), value :: AP
       integer(c_long), value :: strideA
